class TreeNavigator {
    constructor(b, c, start) {
        this.b = b;
        this.c = c;
        if (start) {
            this.a = this.c.getListIndex(start);
        }
        else {
            this.a = -1;
        }
    }
    current() {
        if (this.a < 0 || this.a >= this.b.length) {
            return null;
        }
        return this.b.element(this.a).element;
    }
    previous() {
        this.a--;
        return this.current();
    }
    next() {
        this.a++;
        return this.current();
    }
    first() {
        this.a = 0;
        return this.current();
    }
    last() {
        this.a = this.b.length - 1;
        return this.current();
    }
}
